{"cmd":"python - <<'PY'
import json, math
obj=json.load(open('benchmark/source_data.json'))
# Build aligned yearly from quarterly for index/pe by averaging within year.
index=obj['nasdaq_index']['data']
pe=obj['pe_ratio']['data']

def year_from_label(lbl):
    return int(lbl.split('-')[0])

def quarter_from_label(lbl):
    return int(lbl.split('Q')[1])

# For each era and year, compute mean index and mean PE (PE sparse)
from collections import defaultdict
idx_yr=defaultdict(list)
pe_yr=defaultdict(list)
for d in index:
    idx_yr[(d['era'], year_from_label(d['label']))].append(d['index_value'])
for d in pe:
    pe_yr[(d['era'], year_from_label(d['label']))].append(d['pe'])

for era in ['Dot-com','AI']:
    years=sorted({y for (e,y) in idx_yr if e==era})
    print('\n',era,'years',years)
    for y in years:
        idx=sum(idx_yr[(era,y)])/len(idx_yr[(era,y)])
        pes=pe_yr.get((era,y),[])
        peavg=sum(pes)/len(pes) if pes else None
        print(y,'idx_mean',round(idx,1),'pe_mean',round(peavg,1) if peavg else None,'pe_n',len(pes))
PY"}

